import {highlightHtml,evidencePreview} from './report-highlight.mjs';
import {sliceCp} from './engine.mjs';
import {publicSourceHref as sourceHref} from './source-url.mjs';
import {reportDocument,reportDate,reportEscape as esc} from '../reports/report-document.mjs';
// A presentation/export view only: stored evidence, source text, match offsets
// and original report objects stay unchanged.
export function sourceExportView(source){
 if(!source||typeof source!=='object')return source;
 const url=sourceHref(source.url);
 return {...source,url,...(source.url&&!url?{urlRedacted:true}:{})};
}
export function reportExportView(report){
 return {...report,...(Array.isArray(report.sources)?{sources:report.sources.map(sourceExportView)}:{}),...(report.web&&typeof report.web==='object'?{web:{...report.web,...(Array.isArray(report.web.sources)?{sources:report.web.sources.map(sourceExportView)}:{})}}:{})};
}
export function sourceCopyText(source){
 const safe=sourceExportView(source);
 return `${safe.title}\n作者：${safe.authors?.join('、')||'未提供'}\n年份：${safe.year||'未提供'}\n来源：${safe.provider||'未提供'}\nDOI：${safe.doi||'未提供'}\nURL：${safe.url||(safe.urlRedacted?'链接已隐藏：未通过公开来源安全检查':'未提供')}`;
}
const fmt=n=>Number(n||0).toLocaleString('zh-CN');
const pct=n=>Number.isFinite(n)?(n*100).toFixed(1):'—';
const metric=(label,value,note='')=>`<div class="report-metric"><small>${esc(label)}</small><strong>${esc(value)}</strong>${note?`<em>${esc(note)}</em>`:''}</div>`;
export function webCoverageHtml(report){
 const web=report.web||{},n=key=>Number.isFinite(Number(web[key]))?Math.max(0,Number(web[key])):0;
 return `<section class="report-panel"><h2 class="report-section-title">公开来源检索范围与访问记录</h2><p>抽样检索 ${n('sampledParagraphs')} / ${n('totalParagraphs')} 段 · ${n('queries')} 次检索 · ${n('candidateSources')} 份候选来源 · 实际取得 ${n('fetchedSources')} 份 · 未能取得 ${n('failedSources')} 份。</p><p class="report-muted">仅抽样段落用于查找候选来源；取得的来源正文与参与检测的全文逐字比对。搜索结果摘要不直接计分。本次并未检索全部互联网、封闭学术库或付费全文。</p>${web.searchComplete===false?'<p>本次检索或来源读取未完整完成，结果范围受限。</p>':''}${Array.isArray(web.limitations)&&web.limitations.length?`<ul class="report-notes">${web.limitations.map(value=>`<li>${esc(value)}</li>`).join('')}</ul>`:''}${Array.isArray(web.sources)&&web.sources.length?`<table class="report-table"><thead><tr><th>候选来源</th><th>读取状态</th></tr></thead><tbody>${web.sources.map(source=>{const href=sourceHref(source.url);return `<tr><td>${esc(source.title||'公开来源')}<div class="report-source-info">${href?`<a href="${esc(href)}" rel="noreferrer noopener">${esc(href)}</a>`:'来源链接未记录'}</div></td><td>${['fetched','completed','success','readable'].includes(source.status)?'已取得正文':'未取得可用正文'}${source.error?`<div class="report-source-info">${esc(source.error)}</div>`:''}</td></tr>`;}).join('')}</tbody></table>`:''}</section>`;
}
export function reportHtml(report){
 const sources=report.sources||[],sections=report.sections||[],included=sections.filter(s=>s.included),sourceMap=new Map(sources.map((s,i)=>[s.id,{...s,number:i+1}])),isDemo=report.mode==='demo'||sources.some(s=>s.kind==='demo'),isWeb=report.mode==='web';let evidenceBudget=120;const webEvidenceBudget={remaining:5000,perSource:new Map()};
 const scope=isWeb?'公开网页可访问来源（抽样检索）':isDemo?'演示材料与指定对照正文':'用户提供的本地对照正文';
 const sourceRows=sources.map((s,i)=>`<tr><td style="width:7%">${i+1}</td><td><b>${esc(s.title)}</b><div class="report-source-info">${esc(s.authors?.join('、')||'作者未提供')} · ${esc(s.year||'年份未提供')}</div></td><td style="width:22%">${fmt(s.overlapChars)}<div class="report-bar"><span style="width:${Math.min(100,Math.max(0,(s.overlapChars||0)/Math.max(1,report.totalChars)*100))}%"></span></div></td></tr>`).join('');
 const summary=`<section class="report-panel"><h2 class="report-section-title">检测结果总览</h2><div class="report-metrics">${metric(isWeb?'文字重复率（本次来源范围）':'文字相似占比',pct(report.ratio)+'%','实际匹配区间合并去重')}${metric(isWeb?'引用处理':'去除识别引用后',isWeb?'需人工核对':pct(report.uncitedRatio)+'%',isWeb?'本次未自动扣除引用':'引用识别范围有限，需核对')}${metric('参与检测字符',fmt(report.totalChars),'字母与数字，不含标点空白')}${metric('匹配字符',fmt(report.similarChars),`${report.sourceCount||0} 个命中来源 / ${sources.length} 份对照材料`)}</div><p class="report-muted">${isWeb?'上述结果仅针对本次实际取得的公开来源正文；':'上述结果仅针对本次实际提供的材料；'}“未发现匹配”不代表在其他数据库或全网范围内不存在相似内容。</p></section>${isWeb?webCoverageHtml(report):''}<section class="report-panel"><h2 class="report-section-title">章节检测结果</h2><table class="report-table"><thead><tr><th style="width:42%">章节名称</th><th>检测字符</th><th>匹配字符</th><th>相似占比</th></tr></thead><tbody>${sections.map(s=>`<tr><td>${esc(s.title)}${s.included?'':' <span class="report-badge">未参与检测</span>'}</td><td>${s.included?fmt(s.totalChars):'—'}</td><td>${s.included?fmt(s.similarChars):'—'}</td><td>${s.included?pct(s.ratio)+'%':'—'}</td></tr>`).join('')}</tbody></table></section><section class="report-panel"><h2 class="report-section-title">相似来源概览</h2>${sources.length?`<table class="report-table"><thead><tr><th style="width:7%">编号</th><th>对照材料</th><th style="width:22%">命中字符</th></tr></thead><tbody>${sourceRows}</tbody></table>`:'<div class="report-empty">没有记录可展示的来源材料。</div>'}<p class="report-muted">同一正文片段可能对应多个来源，各来源命中字符不可直接相加。</p></section>`;
 const body=`<section class="report-panel report-page-break"><h2 class="report-section-title">全文标注与片段对照</h2><div class="report-legend"><span><i style="background:#efaea9"></i>实际文字匹配</span><span><i style="background:#a1d9c4"></i>匹配中的已识别引用</span><span><i style="background:#dce2eb"></i>未参与检测</span></div><p class="report-muted">正文标注保留全部实际匹配。片段对照每段最多展示 12 个代表区间、整份 HTML 最多 120 个，完整区间保留在 JSON 报告中。</p>${sections.map(s=>`<div class="${s.included?'':'report-excluded'}"><div class="report-section-head"><h3>${esc(s.title)}</h3><span>${s.included?pct(s.ratio)+'%':'未参与检测'}</span></div>${(s.paragraphs||[]).map((p,index)=>{const rows=s.included?evidencePreview(p.matches||[],Math.min(12,evidenceBudget)):[];evidenceBudget-=rows.length;return `<div class="report-paragraph"><div class="report-paragraph-header">第 ${index+1} 段${s.included&&p.matches?.length?` · ${p.matches.length} 个匹配区间`:''}</div><p class="report-text">${s.included?highlightHtml(p.text,p.matches||[]):esc(p.text)}</p>${rows.map(m=>{const source=sourceMap.get(m.sourceId);if(!source)return '';let sourceSnippet=sliceCp(source.text,...m.sourceRange),originalSnippet=sliceCp(p.text,...m.range),snippetOmitted=false;if(isWeb){const originalLength=Array.from(sourceSnippet).length,available=Math.max(0,Math.min(240,1200-(webEvidenceBudget.perSource.get(source.id)||0),webEvidenceBudget.remaining));sourceSnippet=Array.from(sourceSnippet).slice(0,available).join('');originalSnippet=Array.from(originalSnippet).slice(0,Math.min(240,available)).join('');const used=Array.from(sourceSnippet).length;webEvidenceBudget.remaining-=used;webEvidenceBudget.perSource.set(source.id,(webEvidenceBudget.perSource.get(source.id)||0)+used);snippetOmitted=used<originalLength;}return `<div class="report-evidence"><div class="report-evidence-head"><b>来源 [${source.number}] ${esc(source.title)}</b><div class="report-source-info">${m.citationStatus==='verified_quotation'?'含已识别引用，仍需核对':'未识别为引用'} · ${esc(source.authors?.join('、')||'作者未提供')} · ${esc(source.year||'年份未提供')}</div></div><div class="report-evidence-body report-pair"><div><small>论文匹配片段</small><p class="report-text">${esc(originalSnippet)}</p></div><div><small>来源对应片段</small><p class="report-text">${esc(sourceSnippet)}</p>${snippetOmitted?'<p class="report-muted">片段已省略；完整来源请访问原网页。</p>':''}</div></div></div>`;}).join('')}</div>`;}).join('')}</div>`).join('')}</section><section class="report-panel report-page-break"><h2 class="report-section-title">对照材料与来源信息</h2>${sources.map((s,i)=>{const href=sourceHref(s.url);return `<article class="report-evidence"><div class="report-evidence-head"><h3 class="report-source-title">[${i+1}] ${esc(s.title)}</h3><div class="report-source-info">${esc(s.authors?.join('、')||'作者未提供')} · ${esc(s.year||'年份未提供')} · ${esc(s.provider||'来源未提供')}</div></div><div class="report-evidence-body"><p class="report-source-info">DOI：${esc(s.doi||'未提供')}<br>URL：${href?`<a href="${esc(href)}" rel="noreferrer noopener">${esc(href)}</a>`:(s.url?'链接已隐藏：未通过公开来源安全检查':'未提供')}<br>材料类型：${isWeb?'公开网页实际取得正文':s.kind==='demo'?'演示材料':'用户提供，未联网核验'}${isWeb?`<br>读取时间：${esc(reportDate(s.fetchedAt))}<br>内容校验：${esc(s.contentHash||'未记录')}`:''}</p>${isWeb?'<p class="report-muted">仅展示与本次文稿有关的对照片段，不附录来源网页全文。命中证据见上方正文标注与片段对照。</p>':`<p class="report-text">${esc(s.text)}</p>`}</div></article>`;}).join('')}</section><section class="report-panel"><h2 class="report-section-title">检测口径与使用说明</h2><ol class="report-notes"><li>总相似占比 = 合并去重后的匹配字符数 ÷ 参与检测的有效正文字符数。同一字符命中多个来源只计算一次。</li><li>字符统计包含 Unicode 字母与数字，不含标点空白。仅本次确认的 ${included.length} 个章节参与计分。</li><li>引用排除规则：${esc(report.citationPolicy||'未记录，请人工核对')}。</li><li>${isWeb?'本报告仅使用本次抽样检索中实际可访问的公开来源，不覆盖全部互联网或封闭学术库；未发现匹配不代表不存在重复。':'本报告未检索在线学术数据库。'}不包含语义相似度、AI 率或外部数据库检测结果，不等同于知网、万方、维普检测。</li><li>报告编号仅用于定位这份 PaperKnow 记录，不代表第三方认证或官方防伪编号。修改后的正文需要重新检测，原报告数值保持不变。</li></ol></section>`;
 return reportDocument({title:report.title,type:isWeb?'论文重复率检测报告':'文本相似性检测报告',id:report.id,createdAt:report.createdAt,scope,metadata:[['学段 / 身份',report.degree||'未提供'],['原文件',report.fileName||'粘贴正文'],['报告状态',report.complete===false?'未完整完成':'比对已完成']],notice:isWeb?'PaperKnow 公开来源比对报告。仅将有限段落用于联网检索，取得来源后与全文逐字比对；未发现匹配不等于不存在重复，不代表全网或学校数据库查重结果。':'本地材料比对报告，未检索在线学术数据库。结果仅来自本次指定材料中的实际文字匹配，适合用于来源核对和修改参考。',summary,body,demo:isDemo});
}
